"""AFAB pipeline-parallel training helper for Hugging Face LLaMA models."""

import inspect
from typing import List

import torch
import torch.distributed as dist
import torch.nn.functional as F


def _layer_forward(layer, hidden, position_ids):
    """Call a LlamaDecoderLayer across several transformers API versions."""
    try:
        params = inspect.signature(layer.forward).parameters
    except (TypeError, ValueError):
        params = {}

    kwargs = {}
    if "attention_mask" in params:
        kwargs["attention_mask"] = None
    if "position_ids" in params:
        kwargs["position_ids"] = position_ids
    if "past_key_value" in params:
        kwargs["past_key_value"] = None
    if "past_key_values" in params:
        kwargs["past_key_values"] = None
    if "use_cache" in params:
        kwargs["use_cache"] = False
    if "cache_position" in params:
        kwargs["cache_position"] = position_ids

    # Newer transformers versions may expect precomputed rotary embeddings.
    if "position_embeddings" in params:
        rotary = getattr(layer, "rotary_emb", None)
        if rotary is None:
            rotary = getattr(getattr(layer, "self_attn", None), "rotary_emb", None)
        if rotary is not None:
            try:
                kwargs["position_embeddings"] = rotary(hidden, position_ids)
            except TypeError:
                kwargs["position_embeddings"] = rotary(hidden, position_ids, None)

    out = layer(hidden, **kwargs)
    return out[0] if isinstance(out, (tuple, list)) else out


def _balanced_range(num_layers, rank, world_size):
    """Return a contiguous, approximately equal layer interval for rank."""
    start = (num_layers * rank) // world_size
    end = (num_layers * (rank + 1)) // world_size
    return start, end


def _send(tensor, peer):
    dist.send(tensor=tensor.contiguous(), dst=peer)


def _recv_like(shape, device, dtype, peer):
    result = torch.empty(shape, device=device, dtype=dtype)
    dist.recv(tensor=result, src=peer)
    return result


def train_step_pipeline_afab(model, inputs, targets, device, dtype):
    """Run one all-forward/all-backward pipeline training step.

    ``inputs`` and ``targets`` are lists of microbatches.  The function
    performs the forward pass for every microbatch before beginning any
    backward pass.  Gradients are accumulated in the model parameters in the
    usual PyTorch manner; the resulting loss is returned on the last rank and
    ``None`` is returned on other ranks.
    """
    rank = dist.get_rank() if dist.is_available() and dist.is_initialized() else 0
    world_size = dist.get_world_size() if dist.is_available() and dist.is_initialized() else 1
    if len(inputs) != len(targets):
        raise ValueError("inputs and targets must contain the same number of microbatches")
    if not inputs:
        raise ValueError("at least one microbatch is required")

    llama = model.model
    layers = llama.layers
    num_layers = len(layers)
    first, last = _balanced_range(num_layers, rank, world_size)
    is_first = rank == 0
    is_last = rank == world_size - 1
    n_micro = len(inputs)

    # Keep position IDs consistent with the normal LlamaModel forward.
    def make_position_ids(x):
        return torch.arange(x.shape[1], device=device, dtype=torch.long).unsqueeze(0).expand(x.shape[0], -1)

    # A boundary tensor is deliberately detached before communication.  The
    # receiving side makes it a leaf, and the sender later backpropagates from
    # the gradient sent back across that boundary.
    boundary_outputs = []
    received_inputs = []
    losses = []

    # ----------------------------- all forward -----------------------------
    for mb in range(n_micro):
        x = inputs[mb].to(device=device, dtype=torch.long)
        position_ids = make_position_ids(x)

        if is_first:
            hidden = llama.embed_tokens(x).to(device=device, dtype=dtype)
        else:
            hidden_size = getattr(getattr(model, "config", None), "hidden_size", None)
            if hidden_size is None:
                hidden_size = llama.embed_tokens.weight.shape[-1]
            hidden = _recv_like((x.shape[0], x.shape[1], hidden_size), device, dtype, rank - 1)
            hidden.requires_grad_(True)
            received_inputs.append(hidden)

        for layer_idx in range(first, last):
            hidden = _layer_forward(layers[layer_idx], hidden, position_ids)
            if hidden.dtype != dtype:
                hidden = hidden.to(dtype=dtype)

        if is_last:
            hidden = llama.norm(hidden)
            logits = model.lm_head(hidden)
            target = targets[mb].to(device=device, dtype=torch.long)
            loss = F.cross_entropy(
                logits.float().reshape(-1, logits.shape[-1]), target.reshape(-1), reduction="mean"
            ) / n_micro
            losses.append(loss)
        else:
            boundary_outputs.append(hidden)
            _send(hidden.detach().to(device=device, dtype=dtype), rank + 1)

    # ---------------------------- all backward -----------------------------
    # Reverse microbatch order is the standard AFAB reverse drain and avoids
    # requiring any additional activation recomputation.
    for mb in range(n_micro - 1, -1, -1):
        if is_last:
            losses[mb].backward()
            if world_size > 1:
                # The input to the last stage is the received leaf.
                grad = received_inputs[mb].grad
                _send(grad.detach().to(device=device, dtype=dtype), rank - 1)
        else:
            grad_shape = boundary_outputs[mb].shape
            grad = _recv_like(grad_shape, device, dtype, rank + 1)
            boundary_outputs[mb].backward(grad)
            if not is_first:
                input_grad = received_inputs[mb].grad
                _send(input_grad.detach().to(device=device, dtype=dtype), rank - 1)

    if is_last:
        return torch.stack(losses).sum().detach()
    return None
